SELECT sys03_company_menu_id
  FROM sys03_company_menu
 WHERE sys03_company_id = #{companyId}
   AND sys03_menu_id    = #{menuId}
 LIMIT 1

SELECT COUNT(a.*)
  FROM sys03_company_menu a
       INNER JOIN sys06_menu b ON a.sys03_menu_id = b.sys06_menu_id
 WHERE b.sys06_parent_id  = #{parentId}
   AND a.sys03_company_id = #{companyId}
   AND COALESCE(a.sys03_use_yn, 'false') = 'true'

